/* Verified supplementary Year 9 particle-model questions for a locked 15-answer Physics Daily.
   This augments, never overwrites, the school's existing loaded question bank. */
const rows=[["A gas fills the entire container because its particles…",["are fixed in a lattice","move randomly in all directions","have no mass","are larger than liquid particles"],1,"Gas particles move freely and spread to fill the available space."],["In a solid, particles mainly…",["vibrate around fixed positions","move past each other freely","stop moving entirely","flow to the bottom"],0,"Solid particles vibrate about fixed positions."],["Which change takes place when a solid melts?",["gas to liquid","liquid to gas","solid to liquid","liquid to solid"],2,"Melting changes a solid into a liquid."],["Which statement about particles in a liquid is correct?",["They are far apart and have no forces","They can move past neighbouring particles","They cannot move at all","They form a fixed regular lattice"],1,"Liquid particles remain close but can move past one another."],["When the temperature of a substance increases, its particles usually…",["have less average kinetic energy","get physically bigger","gain average kinetic energy","lose their mass"],2,"A rise in temperature corresponds to higher average particle kinetic energy."],["What happens to the mass of water when it freezes in a closed container?",["It doubles","It remains the same","It disappears","It depends on colour"],1,"Changing state does not change the total mass in a closed system."],["Which state has a definite volume but takes the shape of its container?",["solid","liquid","gas","vacuum"],1,"A liquid keeps approximately the same volume but changes shape."],["Why can gases be compressed easily?",["Their particles shrink","There are relatively large gaps between particles","They have no kinetic energy","Their particles are motionless"],1,"Gas particles are widely spaced, leaving room to move closer."],["What is the name of the change from a gas directly to a solid?",["sublimation","condensation","deposition","evaporation"],2,"Deposition is the direct change from gas to solid."],["During boiling of a pure liquid at constant pressure, supplied energy mainly…",["increases temperature without limit","changes the state by separating particles","destroys the particles","decreases mass"],1,"Latent heat changes the arrangement and separation of particles."],["Which process occurs at the surface of a liquid below its boiling point?",["freezing","evaporation","condensation","deposition"],1,"Evaporation can occur from a liquid surface below boiling."],["Which description fits condensation?",["liquid to gas","gas to liquid","solid to gas","solid to liquid"],1,"Condensation changes a gas into a liquid."],["What is diffusion?",["Particles moving from a region of higher to lower concentration overall","Energy being created from nothing","Solid particles disappearing","Particles increasing in size"],0,"Random particle motion produces a net spread from higher to lower concentration."],["Which change requires energy input to overcome attractions between particles?",["condensation","freezing","melting","deposition"],2,"Melting requires energy to loosen the particles from a solid structure."],["A balloon expands as the gas inside warms because…",["gas particles are created","particles move faster and exert greater pressure if volume is held fixed","particles become heavier","the air becomes a solid"],1,"Heating raises average kinetic energy, leading to more frequent and forceful collisions."]];
const topicId="phys-y9-p1";
const additions=rows.map(([prompt,options,index,explanation],i)=>({
 id:topicId+"-daily-expansion-"+String(i+1).padStart(2,"0"),
 subject:"physics",year:9,topicId,
 topic:"Kinetic theory and the particle model — solids, liquids and gases",
 prompt,format:"mc_single",options,
 answer:{mode:"choice",accepted:[options[index]]},
 feedback:{short:explanation},stimulus:{text:""},
 status:"enabled",formal:true,difficulty:1+(i%3),
 task:{label:"CHOOSE THE ANSWER",instruction:prompt}
}));
export function extendYear9ParticleQuestions(questions,{subject,year,topicId:assignedTopic,taskId,locked}={}){
 const original=Array.isArray(questions)?questions:[];
 if(!locked||subject!=="physics"||Number(year)!==9||assignedTopic!==topicId||taskId!=="year9-light")
  return original;
 const seen=new Set(original.map(q=>String(q?.id)));
 return original.concat(additions.filter(q=>!seen.has(q.id)));
}
